// Список всех шагов. key — клавиша, dx и dy — на сколько клеток карты сдвигаемся
export const MOVES = [                                   // export — чтобы другие файлы могли взять список
  { key: 'q', dx: -1, dy:  0 },                          // вверх-влево по экрану, 1 клетка
  { key: 'e', dx:  0, dy: -1 },                          // вверх-вправо, 1 клетка
  { key: 'z', dx:  0, dy:  1 },                          // вниз-влево, 1 клетка
  { key: 'c', dx:  1, dy:  0 },                          // вниз-вправо, 1 клетка
  { key: 'w', dx: -1, dy: -1 },                          // ровно вверх (2 клетки по диагонали)
  { key: 's', dx:  1, dy:  1 },                          // ровно вниз
  { key: 'a', dx: -1, dy:  1 },                          // ровно влево
  { key: 'd', dx:  1, dy: -1 },                          // ровно вправо
];                                                       // конец списка

// Стрелки делают то же, что W/A/S/D: «название стрелки» -> «буква»
export const ALIAS = {                                   // объект-словарь
  arrowup: 'w', arrowdown: 's', arrowleft: 'a', arrowright: 'd',
};                                                       // конец словаря
